//! Identifiers shared across the domain. New ids are generated by the runtime and arrive in events,
//! so core stays deterministic.

use std::fmt;

use serde::{Deserialize, Serialize};

/// A shepherd session. Format is opaque to core (the runtime uses `s_<ulid>`).
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct SessionId(String);

/// A machine running a shepherd host. Format is opaque to core.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct MachineId(String);

macro_rules! string_id {
    ($t:ident) => {
        impl $t {
            pub fn new(id: impl Into<String>) -> Self {
                Self(id.into())
            }

            pub fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl fmt::Display for $t {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str(&self.0)
            }
        }
    };
}

string_id!(SessionId);
string_id!(MachineId);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_serialize_as_plain_strings() {
        let id = SessionId::new("s_01");
        assert_eq!(serde_json::to_string(&id).unwrap(), "\"s_01\"");
        assert_eq!(serde_json::from_str::<SessionId>("\"s_01\"").unwrap(), id);
    }
}
